class GqlScalarPropertyOptimizerTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI OWNER = VF.createIRI("urn:owner");
	private static final IRI PROPERTY = VF.createIRI("urn:property");

	@Test
	void propertyValidationIsFatalAndCannotBeDiscardedOrFreelyReordered() {
		GqlScalarProperty property = property();
		Extension materialization = new Extension(new SingletonSet(), new ExtensionElem(property, "property"));
		var safety = QueryEvaluationUtility.querySafetySnapshot(materialization);

		assertThat(safety.isRepeatable(property)).isFalse();
		assertThat(safety.isRepeatable(materialization)).isFalse();
		assertThat(safety.mayRaiseQueryFatalError(property)).isTrue();
		assertThat(safety.mayRaiseQueryFatalError(materialization)).isTrue();
		assertThat(safety.usesMappingParameterizedEvaluation(property)).isTrue();
		assertThat(QueryEvaluationUtility.canDiscardWithoutEvaluation(materialization)).isFalse();
		assertThat(AlgebraEvaluationSafety.isRepeatable(property)).isFalse();
		assertThat(AlgebraEvaluationSafety.isRepeatable(materialization)).isFalse();
	}

	@Test
	void aRejectingFilterCannotMoveBeforePropertyValidation() {
		Extension materialization = new Extension(new SingletonSet(), new ExtensionElem(property(), "property"));
		QueryRoot root = new QueryRoot(new Filter(materialization, new ValueConstant(BooleanLiteral.FALSE)));
		new FilterOptimizer().optimize(root, null, EmptyBindingSet.getInstance());

		assertCardinalityFailure(root);
	}

	@Test
	void joinReorderingCannotMoveALaterEmptyPatternBeforePropertyValidation() {
		Extension materialization = new Extension(new SingletonSet(), new ExtensionElem(property(), "property"));
		StatementPattern later = new StatementPattern(new Var("laterSubject", OWNER),
				new Var("laterPredicate", VF.createIRI("urn:missing")), new Var("laterObject", OWNER));
		QueryRoot root = new QueryRoot(new Join(materialization, later));
		new QueryJoinOptimizer(new EvaluationStatistics(), source()).optimize(root, null,
				EmptyBindingSet.getInstance());

		assertCardinalityFailure(root);
	}

	private static GqlScalarProperty property() {
		return new GqlScalarProperty(new ValueConstant(OWNER), "subject", "value",
				new StatementPattern(new Var("subject"), new Var("predicate", PROPERTY), new Var("value")));
	}

	private static void assertCardinalityFailure(TupleExpr expression) {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source(), null);
		var prepared = strategy.precompile(expression);
		assertThatThrownBy(() -> {
			try (var rows = prepared.evaluate(EmptyBindingSet.getInstance())) {
				while (rows.hasNext()) {
					rows.next();
				}
			}
		}).isInstanceOf(QueryEvaluationException.class).hasMessageContaining("multiple");
	}

	private static TripleSource source() {
		return new EmptyTripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
					Resource... contexts) {
				if (PROPERTY.equals(predicate)) {
					return new CloseableIteratorIteration<>(List.of(
							VF.createStatement(OWNER, PROPERTY, VF.createLiteral("first")),
							VF.createStatement(OWNER, PROPERTY, VF.createLiteral("second"))).iterator());
				}
				return EMPTY_ITERATION;
			}
		};
	}
}
